// Damage per source, from the design doc. Smaller rocks hurt less.
export const DAMAGE = { shot: 12, beam: 30, blast: 25, rock: 18, chunk: 6 };
export const INVULNERABLE_TICKS = 60;

// Applies one hit: the shield absorbs first, then health.
// The run ends only when health reaches zero.
export function applyHit(ship, source) {
  if (ship.invulnerableTicks > 0) return ship;
  const amount = DAMAGE[source];
  const shield = Math.max(0, ship.shield - amount);
  const rest = amount - (ship.shield - shield);
  const health = Math.max(0, ship.health - rest);
  return {
    ...ship,
    shield,
    health,
    destroyed: health === 0,
    invulnerableTicks: health > 0 ? INVULNERABLE_TICKS : 0,
  };
}

// Ends the run at once, with a reason for the game-over screen.
export function explodeShip(state, reason) {
  return { ...state, ship: { ...state.ship, destroyed: true, reason } };
}

import { moveAsteroids } from './physics.js';

export function tickHazards(state) {
  return moveAsteroids(state);
}

import { test, expect } from 'vitest';
import { applyHit, DAMAGE, INVULNERABLE_TICKS } from '../src/damage.js';

const ship = (o) => ({ health: 100, shield: 0, invulnerableTicks: 0, ...o });

test('a hit costs the damage its source deals', () => {
  const hit = applyHit(ship(), 'chunk');
  expect(hit.health).toBe(100 - DAMAGE.chunk);
  expect(hit.destroyed).toBe(false);
  expect(hit.invulnerableTicks).toBe(INVULNERABLE_TICKS);
});

test('the shield absorbs damage first', () => {
  const hit = applyHit(ship({ shield: 20 }), 'beam');
  expect(hit.shield).toBe(0);
  expect(hit.health).toBe(90);
});

test('a hit while invulnerable costs nothing', () => {
  const s = ship({ invulnerableTicks: 30 });
  expect(applyHit(s, 'shot')).toBe(s);
});

test('zero health ends the run', () => {
  expect(applyHit(ship({ health: 5 }), 'rock').destroyed).toBe(true);
});

import { test, expect } from 'vitest';
import { runSeeded } from '../src/run.js';

// Every destroyed run must end on a recorded hit, however long it lasts.
test('nothing destroys the ship without a hit, across 500 seeds', () => {
  for (let seed = 1; seed <= 500; seed++) {
    const run = runSeeded({ seed, ticks: 20000 });
    if (run.destroyed) expect(run.lastHit).not.toBeNull();
  }
});
